 38	    /**
 39	     * Try to get the next unique notification id that isn't already being used by the app.
 40	     *
 41	     * Termux app and its plugin must use unique notification ids from the same pool due to usage of android:sharedUserId.
 42	     * https://commonsware.com/blog/2017/06/07/jobscheduler-job-ids-libraries.html
 43	     *
 44	     * @param context The {@link Context} for operations.
 45	     * @return Returns the notification id that should be safe to use.
 46	     */
 47	    public synchronized static int getNextNotificationId(final Context context) {
 48	        if (context == null) return TermuxPreferenceConstants.TERMUX_APP.DEFAULT_VALUE_KEY_LAST_NOTIFICATION_ID;
 49	
 50	        TermuxAppSharedPreferences preferences = TermuxAppSharedPreferences.build(context);
 51	        if (preferences == null) return TermuxPreferenceConstants.TERMUX_APP.DEFAULT_VALUE_KEY_LAST_NOTIFICATION_ID;
 52	
 53	        int lastNotificationId = preferences.getLastNotificationId();
 54	
 55	        int nextNotificationId = lastNotificationId + 1;
 56	        while(nextNotificationId == TermuxConstants.TERMUX_APP_NOTIFICATION_ID || nextNotificationId == TermuxConstants.TERMUX_RUN_COMMAND_NOTIFICATION_ID) {
 57	            nextNotificationId++;
 58	        }
 59	
 60	        if (nextNotificationId == Integer.MAX_VALUE || nextNotificationId < 0)
 61	            nextNotificationId = TermuxPreferenceConstants.TERMUX_APP.DEFAULT_VALUE_KEY_LAST_NOTIFICATION_ID;
 62	
 63	        preferences.setLastNotificationId(nextNotificationId);
 64	        return nextNotificationId;
 65	    }
